#!/usr/bin/env python3
from pathlib import Path
import base64
import re
import zlib

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"Expected exactly one match in {path}, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


# Test-only UI source: generated from the standalone MainActivity visual language so the
# embedded settings page and standalone module page stay visually aligned.
embedded_ui = ROOT / "app/src/main/java/com/rww/wetypeswipe/EmbeddedSettingsUi.java"
embedded_ui.write_text(zlib.decompress(base64.b64decode(
    ""
)).decode("utf-8"), encoding="utf-8")

main_hook = ROOT / "app/src/main/java/com/rww/wetypeswipe/MainHook.java"
replace_once(
    main_hook,
    'logInfo("v1.11.6-test3 entered target package; verified view-touch settings unlock enabled");',
    'logInfo("v1.11.6-test4 entered target package; unified UI five-tap settings enabled");',
)
replace_once(main_hook, 'after == 6', 'after == 4')
replace_once(main_hook, '+ after + "/7 activity="', '+ after + "/5 activity="')
text = main_hook.read_text(encoding="utf-8")
text = text.replace('seven-tap', 'five-tap')
main_hook.write_text(text, encoding="utf-8")

main_activity = ROOT / "app/src/main/java/com/rww/wetypeswipe/MainActivity.java"
replace_once(
    main_activity,
    'v1.11.6-test3 · 关于图标七击内置设置',
    'v1.11.6-test4 · 关于图标五击内置设置',
)

gradle_properties = ROOT / "gradle.properties"
properties = gradle_properties.read_text(encoding="utf-8")
properties, code_count = re.subn(r"(?m)^VERSION_CODE=.*$", "VERSION_CODE=48", properties, count=1)
properties, name_count = re.subn(r"(?m)^VERSION_NAME=.*$", "VERSION_NAME=1.11.6-test4", properties, count=1)
if code_count != 1 or name_count != 1:
    raise SystemExit("Could not update VERSION_CODE/VERSION_NAME")
gradle_properties.write_text(properties, encoding="utf-8")

print("Applied v1.11.6-test4 unified embedded UI and five-tap trigger")
